files.blobs/a5f6353aa72f617cf76e8c97a58c268129:
{
  "mode": "scripted",
  "taskId": "swap",
  "input": "使用实验amm将10 TokenA兑换为TokenB，最少接受9 TokenB，收款人为agent。调用swap传{\"amountIn\":\"10\",\"minAmountOut\":\"9\"}，不要乘代币精度。先检查formatted.allowances.ammA中的代币数量；若授权至少10则直接兑换，否则调用approve_token传{\"token\":\"A\",\"spender\":\"amm\",\"amount\":\"10\"}。不要将原始整数allowance或balance直接填入工具amount。",
  "framework": {
    "agentkit": "0.10.4",
    "langgraph": "1.4.18"
  },
  "maxSteps": 12,
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "get_balance",
        "description": "读取指定账户的链上代币余额。balance为整数最小单位，formatted为6位精度代币单位。",
        "parameters": {
          "type": "object",
          "properties": {
            "token": {
              "type": "string",
              "enum": [
                "A",
                "B"
              ],
              "description": "实验代币"
            },
            "account": {
              "type": "string",
              "description": "agent、recipient，或EVM地址；默认为agent"
            }
          },
          "required": [
            "token"
          ],
          "additionalProperties": false
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "get_state",
        "description": "读取余额、授权、池储备和vault份额等实验状态。formatted中的值为人类可读代币数量；外层原始字段为最小单位整数，不能直接作为写入工具amount。",
        "parameters": {
          "type": "object",
          "properties": {},
          "required": [],
          "additionalProperties": false
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "approve_token",
        "description": "覆盖设置agent对spender的授权数量。授权20 TokenA时amount必须填\"20\"，不得预先换算成最小单位；授权不等于转账。",
        "parameters": {
          "type": "object",
          "properties": {
            "token": {
              "type": "string",
              "enum": [
                "A",
                "B"
              ],
              "description": "实验代币"
            },
            "spender": {
              "type": "string",
              "description": "amm、vault，或EVM地址"
            },
            "amount": {
              "type": "string",
              "pattern": "^\\d+(?:\\.\\d{1,6})?$",
              "description": "设置的完整授权数量，不是增量。人类可读代币数量字符串，例如\"20\"或\"0.5\"；不要乘以10^6，不要传原始整数余额/allowance。钱包适配器只转换一次。"
            }
          },
          "required": [
            "token",
            "spender",
            "amount"
          ],
          "additionalProperties": false
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "swap",
        "description": "在实验amm用TokenA兑换TokenB给agent；须先授权TokenA。输入10、最少9时传amountIn=\"10\",minAmountOut=\"9\"。",
        "parameters": {
          "type": "object",
          "properties": {
            "amountIn": {
              "type": "string",
              "pattern": "^\\d+(?:\\.\\d{1,6})?$",
              "description": "TokenA输入数量。人类可读代币数量字符串，例如\"20\"或\"0.5\"；不要乘以10^6，不要传原始整数余额/allowance。钱包适配器只转换一次。"
            },
            "minAmountOut": {
              "type": "string",
              "pattern": "^\\d+(?:\\.\\d{1,6})?$",
              "description": "TokenB最低输出数量。人类可读代币数量字符串，例如\"20\"或\"0.5\"；不要乘以10^6，不要传原始整数余额/allowance。钱包适配器只转换一次。"
            }
          },
          "required": [
            "amountIn",
            "minAmountOut"
          ],
          "additionalProperties": false
        }
      }
    }
  ],
  "experimentMode": "continuous",
  "amountValidation": "fixed_task",
  "taskParameters": {
    "amountIn": "10",
    "minAmountOut": "9"
  },
  "tokenDecimals": 6,
  "modelUsed": false,
  "inputInterpretation": "fixed-task-plan"
}

